import{_ as e}from"./chunks/npu_3510_hw_arch_sync.DHjro_LS.js";import{_ as t}from"./chunks/3510_sync_control_mode_diagram.tNcLb1Xz.js";import{_,o as a,a as r,b as s}from"./app.UgfkfLuP.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"系统同步能力概述","link":"/api/SIMD-API/c_api/sync/system_sync_overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/system_sync_overview.md","filePath":"api/SIMD-API/c_api/sync/system_sync_overview.md","lastUpdated":1793082324000}'),o={name:"api/SIMD-API/c_api/sync/system_sync_overview.md"};function d(n,c,i,y,I,l){return a(),r("div",null,[...c[0]||(c[0]=[s('<div><article class="markdown-body"><h1>系统同步能力概述</h1><p>在Ascend C编程中，同步用于约束AI Core内外不同执行单元的执行先后关系，确保后续指令在依赖的数据、状态或同步信号就绪后再继续执行。由于数据搬运、计算、不同核函数（Kernel）或不同AI Core之间可以并行，如果缺少必要的同步，后续执行单元可能读取到尚未写入完成的数据，或在前序任务未完成时提前执行，导致计算结果错误或执行行为不符合预期。</p><p>AI Core的同步，总共分成2类：<a href="intra_core_sync/intra_core_sync_overview.html">核内同步</a>、<a href="inter_core_sync/inter_core_sync_overview.html">核间同步</a>。</p><p>以下内容展示两类同步的使用场景。</p><ul><li><p>核内同步用于约束同一核内不同硬件流水或同一硬件流水内指令的执行时序。</p><p>例如在AIV中，MTE2单元通过<code>PIPE_MTE2</code>将数据搬入片上存储后，Vector单元才可以通过<code>PIPE_V</code>读取该数据进行计算，此时需要插入<code>PIPE_MTE2</code>到<code>PIPE_V</code>的同步，使<code>PIPE_V</code>等待<code>PIPE_MTE2</code>的前序搬入完成。</p></li><li><p>核间同步用于约束不同核之间的执行时序，参与同步的对象可以是多个AI Core，也可以是同一AI Core内的AIC和AIV。</p><div data-filter="950"><p>如图1所示，针对<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构3510</a>，同一个AI Core内AIV通过<code>PIPE_MTE3</code>将数据从UB搬运到L1 Buffer后，AIC侧<code>PIPE_MTE1</code>才能将L1 Buffer中的数据搬入L0A Buffer和L0B Buffer并继续执行矩阵计算，此时需要让AIC等待AIV的数据搬运完成通知。</p><p>核内同步和核间同步的区别在于：核内同步解决同一核内部硬件流水之间的数据依赖，关注<code>PIPE_MTE2</code>、<code>PIPE_V</code>等流水的先后关系；核间同步解决不同核或不同逻辑核之间的进度依赖，关注AIC、AIV或多个AI Core之间的先后关系。</p><p><strong>图1</strong> <a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构3510</a>架构图 <img src="'+e+'" alt></p></div></li></ul><p>各类同步对应的接口如下。</p><p><strong>表1</strong> 核内同步接口</p><table><thead><tr><th>接口名称</th><th>功能简述</th></tr></thead><tbody><tr><td><a href="intra_core_sync/asc_sync_notify.html">asc_sync_notify</a>/<a href="intra_core_sync/asc_sync_wait.html">asc_sync_wait</a></td><td>多流水同步：同一核内不同流水之间的同步指令。<code>asc_sync_notify</code>负责发送通知，<code>asc_sync_wait</code>负责阻塞直到<code>asc_sync_notify</code>发送通知。</td></tr><tr><td><a href="intra_core_sync/asc_sync_pipe.html">asc_sync_pipe</a></td><td>单流水同步：同一核内相同流水之间的同步指令（不支持<code>PIPE_S</code>单流水同步）。</td></tr><tr><td><a href="intra_core_sync/asc_sync_data_barrier.html">asc_sync_data_barrier</a></td><td>阻塞后续的指令执行，直到所有之前的内存访问指令（需要等待的内存位置可通过参数控制）执行结束。</td></tr><tr><td><a href="intra_core_sync/asc_lock.html">asc_lock</a>/<a href="intra_core_sync/asc_unlock.html">asc_unlock</a></td><td>多流水同步：用于核内异步流水指令之间的同步处理，其功能类似于传统CPU中的锁机制。通过锁定指定流水再释放流水来完成流水间的同步依赖。</td></tr><tr><td><a href="intra_core_sync/asc_sync_vec.html">asc_sync_vec</a></td><td>核内同步易用性接口：针对<code>PIPE_V</code>执行同步操作，保证<code>PIPE_V</code>中前序指令全部完成后，其他流水的后续指令才能开始执行。只能在AIV中调用。</td></tr><tr><td><a href="intra_core_sync/asc_sync_mte2.html">asc_sync_mte2</a></td><td>核内同步易用性接口：针对<code>PIPE_MTE2</code>执行同步操作，保证<code>PIPE_MTE2</code>中前序指令全部完成后，其他流水的后续指令才能开始执行。只能在AIV中调用。</td></tr><tr><td><a href="intra_core_sync/asc_sync_mte3.html">asc_sync_mte3</a></td><td>核内同步易用性接口：针对<code>PIPE_MTE3</code>执行同步操作，保证<code>PIPE_MTE3</code>中前序指令全部完成后，其他流水的后续指令才能开始执行。只能在AIV中调用。</td></tr><tr><td><a href="intra_core_sync/asc_sync.html">asc_sync</a></td><td>全部流水同步：同一核内所有流水之间的同步指令，功能与<code>asc_sync_pipe(PIPE_ALL)</code>等价。阻塞调用点后所有硬件流水的后序指令，直到调用点之前所有硬件流水的前序指令全部完成。</td></tr></tbody></table><p>图2展示了四种同步控制模式，各模式的功能描述如下。该图基于核函数（Kernel）使用<code>__mix__(1, 2)</code>修饰、逻辑核数<code>numBlocks=4</code>的场景配置。</p><ul><li>模式0：AI Core核间的同步控制。对于AIC全核场景，同步所有的AIC核，直到所有的AIC核都执行到<code>asc_sync_inter_arrive</code>时，<code>asc_sync_inter_wait</code>后续的指令才会执行；对于AIV全核场景，同步所有的AIV核，直到所有的AIV核都执行到<code>asc_sync_inter_arrive</code>时，<code>asc_sync_inter_wait</code>后续的指令才会执行。</li><li>模式1：AI Core内部，AIV核之间的同步控制。如果两个AIV核都运行了<code>asc_sync_subblock_arrive</code>，<code>asc_sync_subblock_wait</code>后续的指令才会执行。</li><li>模式2：AI Core内部，AIC与AIV之间的同步控制。在AIC核执行<code>asc_sync_block_arrive</code>之后，两个AIV上<code>asc_sync_block_wait</code>后续的指令才会继续执行；两个AIV都执行<code>asc_sync_block_arrive</code>后，AIC上<code>asc_sync_block_wait</code>后续的指令才能执行。</li><li>模式4：AI Core内部，AIC与单个AIV之间的同步控制。在单个AIV核执行<code>asc_sync_intra_arrive</code>之后，AIC上<code>asc_sync_intra_wait</code>后续的指令才会继续执行；AIC执行<code>asc_sync_intra_arrive</code>后，单个AIV上<code>asc_sync_intra_wait</code>后续的指令才能执行。AIV0与AIV1可单独触发AIC等待。</li></ul><p><strong>图2</strong> 四种核间同步控制模式示意图<a id="fig_sync_control_mode"></a><img src="'+t+'" alt></p><p><strong>表2</strong> 核间同步接口</p><table><thead><tr><th>接口名称</th><th>同步范围</th><th>对应模式</th><th>功能简述</th></tr></thead><tbody><tr><td><a href="inter_core_sync/asc_sync_inter_arrive.html">asc_sync_inter_arrive</a>/<a href="inter_core_sync/asc_sync_inter_wait.html">asc_sync_inter_wait</a></td><td>组间同步，即不同group之间所有block（所有AIC或所有AIV）之间的同步。</td><td>模式0（同步等待全部AIC或全部AIV执行结束）</td><td><code>asc_sync_inter_arrive</code>为生产者，负责发送通知；<code>asc_sync_inter_wait</code>为消费者，负责阻塞等待通知到达。</td></tr><tr><td><a href="inter_core_sync/asc_sync_subblock_arrive.html">asc_sync_subblock_arrive</a>/<a href="inter_core_sync/asc_sync_subblock_wait.html">asc_sync_subblock_wait</a></td><td>组内subblock间的同步，即同一group内不同subblock（AIV）之间的同步。</td><td>模式1（单个AI Core内，全部AIV之间的同步）</td><td><code>asc_sync_subblock_arrive</code>为生产者，负责发送通知；<code>asc_sync_subblock_wait</code>为消费者，负责阻塞等待通知到达。</td></tr><tr><td><a href="inter_core_sync/asc_sync_block_arrive.html">asc_sync_block_arrive</a>/<a href="inter_core_sync/asc_sync_block_wait.html">asc_sync_block_wait</a></td><td>同一group内block（AIC）与所有subblock（AIV）之间的同步。</td><td>模式2（单个AI Core内，AIC与全部AIV之间的同步）</td><td><code>asc_sync_block_arrive</code>为生产者，负责发送通知；<code>asc_sync_block_wait</code>为消费者，负责阻塞等待通知到达。</td></tr><tr><td><a href="inter_core_sync/asc_sync_intra_arrive.html">asc_sync_intra_arrive</a>/<a href="inter_core_sync/asc_sync_intra_wait.html">asc_sync_intra_wait</a></td><td>同一group内block（AIC）与单个subblock（AIV）之间的同步。</td><td>模式4（单个AI Core内，AIC核与单个AIV之间同步）</td><td><code>asc_sync_intra_arrive</code>为生产者，负责发送通知；<code>asc_sync_intra_wait</code>为消费者，负责阻塞等待通知到达。</td></tr></tbody></table></article></div>',1)])])}const P=_(o,[["render",d]]);export{m as __pageData,P as default};
